class Widget {};

void useWidget(std::shared_ptr<Widget> spw) {
    // spw is a copy, reference count is now at least 2.
    // ... uses the widget ...
} // spw goes out of scope, reference count is decremented.

// 1. Resource is created, managed by a shared_ptr.
//    Reference count is 1.
auto spw1 = std::make_shared<Widget>();

// 2. A copy is made.
//    Reference count becomes 2.
auto spw2 = spw1;

// 3. A temporary copy is passed to a function.
//    Reference count becomes 3 inside useWidget, then drops back to 2.
useWidget(spw1);

// 4. One shared_ptr is reset.
//    Reference count drops to 1.
spw2.reset();

// 5. The last shared_ptr goes out of scope.
//    Reference count drops to 0, and the Widget is deleted automatically.
// spw1 is destroyed at the end of its scope.
